digraph G {
graph [fontname="Microsoft YaHei",fontsize=21,label="场站与充电设施｜Chen 局部 E-R 图",labelloc=t,pad="0.45",nodesep="0.44",ranksep="1.0",rankdir=TB,splines=polyline,bgcolor="white",outputorder=edgesfirst];
node [fontname="Microsoft YaHei",fontsize=18,color="#253343",penwidth=1.5,margin="0.15,0.10"];
edge [fontname="Microsoft YaHei",fontsize=15,color="#526171",penwidth=1.2,arrowsize=0.7];
edge [dir=none];
"asset_history" [shape=box,width=2.334,height=1.000,fixedsize=true,style="filled",fillcolor="#dcebf8",label="设备状态历史\nasset_history"];
"asset_history__pk" [shape=ellipse,width=3.754,height=0.906,fixedsize=true,label=<<U>设备状态历史编号</U>>];
"asset_history" -> "asset_history__pk" [color="#77818b",weight=5];
"asset_history__old_state" [shape=ellipse,width=2.578,height=0.906,fixedsize=true,label="变更前状态"];
"asset_history" -> "asset_history__old_state" [color="#77818b",weight=4];
"asset_history__new_state" [shape=ellipse,width=2.578,height=0.906,fixedsize=true,label="变更后状态"];
"asset_history" -> "asset_history__new_state" [color="#77818b",weight=4];
"asset_history__happened_at" [shape=ellipse,width=2.185,height=0.906,fixedsize=true,label="发生时间"];
"asset_history" -> "asset_history__happened_at" [color="#77818b",weight=4];
"asset_request" [shape=box,width=2.802,height=1.000,fixedsize=true,style="filled",fillcolor="#dcebf8",label="设备验收与变更申请\nasset_request"];
"asset_request__pk" [shape=ellipse,width=4.931,height=0.906,fixedsize=true,label=<<U>设备验收与变更申请编号</U>>];
"asset_request" -> "asset_request__pk" [color="#77818b",weight=5];
"asset_request__kind" [shape=ellipse,width=1.401,height=0.906,fixedsize=true,label="类别"];
"asset_request" -> "asset_request__kind" [color="#77818b",weight=4];
"asset_request__state" [shape=ellipse,width=1.401,height=0.906,fixedsize=true,label="状态"];
"asset_request" -> "asset_request__state" [color="#77818b",weight=4];
"asset_request__created_at" [shape=ellipse,width=2.185,height=0.906,fixedsize=true,label="创建时间"];
"asset_request" -> "asset_request__created_at" [color="#77818b",weight=4];
"charger" [shape=box,width=1.449,height=1.000,fixedsize=true,style="filled",fillcolor="#dcebf8",label="充电桩\ncharger"];
"charger__pk" [shape=ellipse,width=2.578,height=0.906,fixedsize=true,label=<<U>充电桩编号</U>>];
"charger" -> "charger__pk" [color="#77818b",weight=5];
"charger__model" [shape=ellipse,width=1.401,height=0.906,fixedsize=true,label="型号"];
"charger" -> "charger__model" [color="#77818b",weight=4];
"charger__rated_kw" [shape=ellipse,width=2.578,height=0.906,fixedsize=true,label="桩额定功率"];
"charger" -> "charger__rated_kw" [color="#77818b",weight=4];
"charger__state" [shape=ellipse,width=1.401,height=0.906,fixedsize=true,label="状态"];
"charger" -> "charger__state" [color="#77818b",weight=4];
"connector" [shape=box,width=1.744,height=1.000,fixedsize=true,style="filled",fillcolor="#dcebf8",label="充电枪\nconnector"];
"connector__pk" [shape=ellipse,width=2.578,height=0.906,fixedsize=true,label=<<U>充电枪编号</U>>];
"connector" -> "connector__pk" [color="#77818b",weight=5];
"connector__gun_position" [shape=ellipse,width=1.793,height=0.906,fixedsize=true,label="枪序号"];
"connector" -> "connector__gun_position" [color="#77818b",weight=4];
"connector__kind" [shape=ellipse,width=1.401,height=0.906,fixedsize=true,label="类别"];
"connector" -> "connector__kind" [color="#77818b",weight=4];
"connector__max_kw" [shape=ellipse,width=2.970,height=0.906,fixedsize=true,label="最大充电功率"];
"connector" -> "connector__max_kw" [color="#77818b",weight=4];
"operator" [shape=box,width=1.597,height=1.000,fixedsize=true,style="filled",fillcolor="#dcebf8",label="运营商\noperator"];
"operator__pk" [shape=ellipse,width=2.578,height=0.906,fixedsize=true,label=<<U>运营商编号</U>>];
"operator" -> "operator__pk" [color="#77818b",weight=5];
"operator__name" [shape=ellipse,width=1.401,height=0.906,fixedsize=true,label="名称"];
"operator" -> "operator__name" [color="#77818b",weight=4];
"station" [shape=box,width=1.449,height=1.000,fixedsize=true,style="filled",fillcolor="#dcebf8",label="场站\nstation"];
"station__pk" [shape=ellipse,width=2.185,height=0.906,fixedsize=true,label=<<U>场站编号</U>>];
"station" -> "station__pk" [color="#77818b",weight=5];
"station__name" [shape=ellipse,width=1.401,height=0.906,fixedsize=true,label="名称"];
"station" -> "station__name" [color="#77818b",weight=4];
"station__address" [shape=ellipse,width=1.401,height=0.906,fixedsize=true,label="地址"];
"station" -> "station__address" [color="#77818b",weight=4];
"station__spaces" [shape=ellipse,width=2.185,height=0.906,fixedsize=true,label="车位总数"];
"station" -> "station__spaces" [color="#77818b",weight=4];
rel_0 [shape=diamond,width=1.545,height=1.013,fixedsize=true,label="运营",fontsize=15];
"operator" -> rel_0 [label="1",minlen=1];
rel_0 -> "station" [label="N",minlen=1];
rel_1 [shape=diamond,width=1.545,height=1.013,fixedsize=true,label="部署",fontsize=15];
"station" -> rel_1 [label="1",minlen=1];
rel_1 -> "charger" [label="N",minlen=1];
rel_2 [shape=diamond,width=1.545,height=1.013,fixedsize=true,label="配置",fontsize=15];
"charger" -> rel_2 [label="1",minlen=1];
rel_2 -> "connector" [label="N",minlen=1];
rel_3 [shape=diamond,width=2.737,height=1.013,fixedsize=true,label="记录桩状态",fontsize=15];
"charger" -> rel_3 [label="0..1",minlen=1];
rel_3 -> "asset_history" [label="N",minlen=1];
rel_4 [shape=diamond,width=2.737,height=1.013,fixedsize=true,label="记录枪状态",fontsize=15];
"connector" -> rel_4 [label="0..1",minlen=1];
rel_4 -> "asset_history" [label="N",minlen=1];
rel_5 [shape=diamond,width=3.356,height=1.013,fixedsize=true,label="申请验收/变更",fontsize=15];
"charger" -> rel_5 [label="1",minlen=1];
rel_5 -> "asset_request" [label="N",minlen=1];
legend [shape=note,width=4.053,height=1.333,fixedsize=true,fontsize=13,label="矩形：实体；菱形：联系；椭圆：业务属性\n下划线：主标识；N：0..N；0..1：可选\n灰色虚框：跨线实体；虚线：逻辑关联\n外键由联系表达；完整字段见 UML 分区图"];
}

digraph G {
graph [fontname="Microsoft YaHei",fontsize=20,label="场站与充电设施｜UML 用例图",labelloc=t,pad="0.45",nodesep="0.44",ranksep="1.0",rankdir=LR,splines=polyline,bgcolor="white",outputorder=edgesfirst];
node [fontname="Microsoft YaHei",fontsize=17,color="#253343",penwidth=1.5,margin="0.15,0.10"];
edge [fontname="Microsoft YaHei",fontsize=14,color="#526171",penwidth=1.2,arrowsize=0.7];
actor_0 [shape=box,width=2.169,height=1.389,fixedsize=true,style=filled,color="white",fillcolor="white",label="平台运营管理员"];
actor_1 [shape=box,width=2.169,height=1.389,fixedsize=true,style=filled,color="white",fillcolor="white",label="场站运维工程师"];
actor_2 [shape=box,width=1.418,height=1.389,fixedsize=true,style=filled,color="white",fillcolor="white",label="车主用户"];
actor_3 [shape=box,width=2.308,height=1.389,fixedsize=true,style=filled,color="white",fillcolor="white",label="设备/心跳模拟器"];
subgraph cluster_system { label="场站与充电设施子系统"; style=rounded; color="#8194a6";
uc_0 [shape=ellipse,width=3.210,height=0.876,fixedsize=true,style=filled,fillcolor="#f3f7fb",label="登记场站与桩枪"];
uc_1 [shape=ellipse,width=2.469,height=0.876,fixedsize=true,style=filled,fillcolor="#f3f7fb",label="验收并投运"];
uc_2 [shape=ellipse,width=3.992,height=0.876,fixedsize=true,style=filled,fillcolor="#f3f7fb",label="申请改造/迁移/退役"];
uc_3 [shape=ellipse,width=2.839,height=0.876,fixedsize=true,style=filled,fillcolor="#f3f7fb",label="审核档案变更"];
uc_4 [shape=ellipse,width=3.580,height=0.876,fixedsize=true,style=filled,fillcolor="#f3f7fb",label="查询场站与可用枪"];
uc_5 [shape=ellipse,width=3.950,height=0.876,fixedsize=true,style=filled,fillcolor="#f3f7fb",label="上报心跳与设备状态"];
uc_6 [shape=ellipse,width=3.950,height=0.876,fixedsize=true,style=filled,fillcolor="#f3f7fb",label="离线扫描并生成待办"];
}
actor_0 -> uc_0 [dir=none];
actor_0 -> uc_1 [dir=none];
actor_1 -> uc_1 [dir=none];
actor_1 -> uc_2 [dir=none];
actor_0 -> uc_3 [dir=none];
actor_2 -> uc_4 [dir=none];
actor_3 -> uc_5 [dir=none];
actor_3 -> uc_6 [dir=none];
}

digraph G {
graph [fontname="Microsoft YaHei",fontsize=19,label="场站与充电设施｜鲁棒图（分析模型，非时序图）",labelloc=t,pad="0.45",nodesep="0.44",ranksep="1.0",rankdir=LR,splines=polyline,bgcolor="white",outputorder=edgesfirst];
node [fontname="Microsoft YaHei",fontsize=16,color="#253343",penwidth=1.5,margin="0.15,0.10"];
edge [fontname="Microsoft YaHei",fontsize=13,color="#526171",penwidth=1.2,arrowsize=0.7];
actor_0 [shape=box,width=1.726,height=1.389,fixedsize=true,color="white",label="管理员/运维"];
actor_1 [shape=box,width=1.594,height=1.389,fixedsize=true,color="white",label="设备模拟器"];
actor_2 [shape=box,width=0.888,height=1.389,fixedsize=true,color="white",label="车主"];
boundary_0 [shape=box,width=2.301,height=1.389,fixedsize=true,color="white",label="设备档案与验收页"];
boundary_1 [shape=box,width=2.197,height=1.389,fixedsize=true,color="white",label="变更申请/审批页"];
boundary_2 [shape=box,width=1.830,height=1.389,fixedsize=true,color="white",label="设备心跳接入"];
boundary_3 [shape=box,width=1.830,height=1.389,fixedsize=true,color="white",label="场站查询接口"];
control_0 [shape=box,width=2.537,height=1.389,fixedsize=true,color="white",label="设施登记与验收控制"];
control_1 [shape=box,width=3.008,height=1.389,fixedsize=true,color="white",label="变更审批及层级约束控制"];
control_2 [shape=box,width=3.008,height=1.389,fixedsize=true,color="white",label="在线状态与离线待办控制"];
control_3 [shape=box,width=2.066,height=1.389,fixedsize=true,color="white",label="可用枪查询控制"];
entity_operator [shape=box,width=1.123,height=1.389,fixedsize=true,color="white",label="运营商"];
entity_station [shape=box,width=0.888,height=1.389,fixedsize=true,color="white",label="场站"];
entity_charger [shape=box,width=1.123,height=1.389,fixedsize=true,color="white",label="充电桩"];
entity_connector [shape=box,width=1.123,height=1.389,fixedsize=true,color="white",label="充电枪"];
entity_asset_request [shape=box,width=2.537,height=1.389,fixedsize=true,color="white",label="设备验收与变更申请"];
entity_asset_history [shape=box,width=1.830,height=1.389,fixedsize=true,color="white",label="设备状态历史"];
actor_0 -> boundary_0 [dir=none];
actor_0 -> boundary_1 [dir=none];
actor_1 -> boundary_2 [dir=none];
actor_2 -> boundary_3 [dir=none];
boundary_0 -> control_0 [label="请求/事件"];
boundary_1 -> control_1 [label="请求/事件"];
boundary_2 -> control_2 [label="请求/事件"];
boundary_3 -> control_3 [label="请求/事件"];
control_0 -> entity_operator [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_0 -> entity_station [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_0 -> entity_charger [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_0 -> entity_connector [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_0 -> entity_asset_request [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_1 -> entity_asset_request [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_1 -> entity_charger [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_1 -> entity_connector [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_2 -> entity_charger [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_2 -> entity_asset_history [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_2 -> entity_asset_request [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_3 -> entity_station [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
control_3 -> entity_connector [dir=both,arrowtail=open,arrowhead=open,color="#3b6d91"];
cross_0 [shape=box,width=2.592,height=0.833,fixedsize=true,style="rounded,dashed",fillcolor="#f2f5f7",label="«control»\nC：告警及断连处置控制",fontsize=14];
control_2 -> cross_0 [style=dashed,label="调用/协作",constraint=false];
cross_1 [shape=box,width=1.974,height=0.833,fixedsize=true,style="rounded,dashed",fillcolor="#f2f5f7",label="«control»\nQ：留枪资格控制",fontsize=14];
control_3 -> cross_1 [style=dashed,label="调用/协作",constraint=false];
control_0 -> control_2 [style=dotted,label="业务协作",constraint=false];
control_1 -> control_2 [style=dotted,label="业务协作",constraint=false];
control_2 -> control_3 [style=dotted,label="业务协作",constraint=false];
legend [shape=note,width=4.287,height=1.000,fixedsize=true,fontsize=12,label="boundary：页面/接入边界；control：业务协调\nentity：领域实体；虚线：跨线控制依赖\n参与者只接边界，边界经控制访问实体"];
}

digraph G {
graph [fontname="Microsoft YaHei",fontsize=18,label="场站与充电设施｜全局 UML 分区详图（完整字段）",labelloc=t,pad="0.45",nodesep="0.44",ranksep="1.0",rankdir=LR,splines=polyline,bgcolor="white",outputorder=edgesfirst];
node [fontname="Microsoft YaHei",fontsize=15,color="#253343",penwidth=1.5,margin="0.15,0.10"];
edge [fontname="Microsoft YaHei",fontsize=12,color="#526171",penwidth=1.2,arrowsize=0.7];
"asset_history" [shape=plain,label=<<TABLE BORDER="1" CELLBORDER="0" CELLSPACING="0" CELLPADDING="7"><TR><TD WIDTH="299" BGCOLOR="#dcebf8"><B>设备状态历史</B><BR/>asset_history</TD></TR><HR/><TR><TD ALIGN="LEFT">PK id : bigint [1]</TD></TR><TR><TD ALIGN="LEFT">FK charger_id : bigint [0..1]</TD></TR><TR><TD ALIGN="LEFT">FK connector_id : bigint [0..1]</TD></TR><TR><TD ALIGN="LEFT">old_state : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">new_state : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">happened_at : datetime(6) [1]</TD></TR></TABLE>>];
"asset_request" [shape=plain,label=<<TABLE BORDER="1" CELLBORDER="0" CELLSPACING="0" CELLPADDING="7"><TR><TD WIDTH="340" BGCOLOR="#dcebf8"><B>设备验收与变更申请</B><BR/>asset_request</TD></TR><HR/><TR><TD ALIGN="LEFT">PK id : bigint [1]</TD></TR><TR><TD ALIGN="LEFT">FK charger_id : bigint [1]</TD></TR><TR><TD ALIGN="LEFT">kind : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">payload : json [1]</TD></TR><TR><TD ALIGN="LEFT">state : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">created_at : datetime(6) [1]</TD></TR><TR><TD ALIGN="LEFT">派生 pending_charger : bigint [0..1]</TD></TR></TABLE>>];
"charger" [shape=plain,label=<<TABLE BORDER="1" CELLBORDER="0" CELLSPACING="0" CELLPADDING="7"><TR><TD WIDTH="290" BGCOLOR="#dcebf8"><B>充电桩</B><BR/>charger</TD></TR><HR/><TR><TD ALIGN="LEFT">PK id : bigint [1]</TD></TR><TR><TD ALIGN="LEFT">FK station_id : bigint [1]</TD></TR><TR><TD ALIGN="LEFT">model : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">rated_kw : numeric(8,2) [1]</TD></TR><TR><TD ALIGN="LEFT">protocol : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">commissioned_on : date [0..1]</TD></TR><TR><TD ALIGN="LEFT">warranty_until : date [0..1]</TD></TR><TR><TD ALIGN="LEFT">heartbeat : datetime(6) [0..1]</TD></TR><TR><TD ALIGN="LEFT">state : varchar(255) [1]</TD></TR></TABLE>>];
"connector" [shape=plain,label=<<TABLE BORDER="1" CELLBORDER="0" CELLSPACING="0" CELLPADDING="7"><TR><TD WIDTH="272" BGCOLOR="#dcebf8"><B>充电枪</B><BR/>connector</TD></TR><HR/><TR><TD ALIGN="LEFT">PK id : bigint [1]</TD></TR><TR><TD ALIGN="LEFT">FK charger_id : bigint [1]</TD></TR><TR><TD ALIGN="LEFT">gun_position : integer [1]</TD></TR><TR><TD ALIGN="LEFT">kind : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">interface : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">max_kw : numeric(8,2) [1]</TD></TR><TR><TD ALIGN="LEFT">state : varchar(255) [1]</TD></TR></TABLE>>];
"operator" [shape=plain,label=<<TABLE BORDER="1" CELLBORDER="0" CELLSPACING="0" CELLPADDING="7"><TR><TD WIDTH="240" BGCOLOR="#dcebf8"><B>运营商</B><BR/>operator</TD></TR><HR/><TR><TD ALIGN="LEFT">PK id : bigint [1]</TD></TR><TR><TD ALIGN="LEFT">name : varchar(255) [1]</TD></TR></TABLE>>];
"station" [shape=plain,label=<<TABLE BORDER="1" CELLBORDER="0" CELLSPACING="0" CELLPADDING="7"><TR><TD WIDTH="299" BGCOLOR="#dcebf8"><B>场站</B><BR/>station</TD></TR><HR/><TR><TD ALIGN="LEFT">PK id : bigint [1]</TD></TR><TR><TD ALIGN="LEFT">FK operator_id : bigint [1]</TD></TR><TR><TD ALIGN="LEFT">name : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">address : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">longitude : numeric(9,6) [0..1]</TD></TR><TR><TD ALIGN="LEFT">latitude : numeric(8,6) [0..1]</TD></TR><TR><TD ALIGN="LEFT">spaces : integer [1]</TD></TR><TR><TD ALIGN="LEFT">opens : time [1]</TD></TR><TR><TD ALIGN="LEFT">closes : time [1]</TD></TR><TR><TD ALIGN="LEFT">parking_note : varchar(255) [1]</TD></TR><TR><TD ALIGN="LEFT">enabled : boolean [1]</TD></TR></TABLE>>];
"station" -> "operator" [arrowhead=none,taillabel="0..*",headlabel="1",label="operator_id",labeldistance=1.7];
"charger" -> "station" [arrowhead=none,taillabel="0..*",headlabel="1",label="station_id",labeldistance=1.7];
"connector" -> "charger" [arrowhead=none,taillabel="0..*",headlabel="1",label="charger_id",labeldistance=1.7];
"asset_history" -> "charger" [arrowhead=none,taillabel="0..*",headlabel="0..1",label="charger_id",labeldistance=1.7];
"asset_history" -> "connector" [arrowhead=none,taillabel="0..*",headlabel="0..1",label="connector_id",labeldistance=1.7];
"asset_request" -> "charger" [arrowhead=none,taillabel="0..*",headlabel="1",label="charger_id",labeldistance=1.7];
}

digraph G {
graph [fontname="Microsoft YaHei",fontsize=21,label="充电估算与到站排队｜Chen 局部 E-R 图",labelloc=t,pad="0.45",nodesep="0.44",ranksep="1.0",rankdir=TB,splines=polyline,bgcolor="white",outputorder=edgesfirst];
node [fontname="Microsoft YaHei",fontsize=18,color="#253343",penwidth=1.5,margin="0.15,0.10"];
edge [fontname="Microsoft YaHei",fontsize=15,color="#526171",penwidth=1.2,arrowsize=0.7];
edge [dir=none];
"account" [shape=box,width=2.272,height=1.375,fixedsize=true,style="filled,dashed",fillcolor="#f3f4f5",label="登录账户及会员\n【外部引用】\naccount"];
