"connector" [shape=box,width=2.007,height=1.375,fixedsize=true,style="filled,dashed",fillcolor="#f3f4f5",label="充电枪\n【外部引用】\nconnector"];
"gun_hold" [shape=box,width=1.742,height=1.000,fixedsize=true,style="filled",fillcolor="#e1f3f0",label="充电枪保留\ngun_hold"];
