"queue_call" [shape=box,width=1.892,height=1.000,fixedsize=true,style="filled",fillcolor="#e1f3f0",label="叫号记录\nqueue_call"];
"queue_call__pk" [shape=ellipse,width=2.970,height=0.906,fixedsize=true,label=<<U>叫号记录编号</U>>];
